codeExample.code:
// 示例数组：一组数字
const numbers = [1, 2, 3, 4, 5];

// 使用map将每个元素乘以2，返回新数组
const doubled = numbers.map(num => num * 2);
console.log('map结果:', doubled); // 输出: [2, 4, 6, 8, 10]

// 使用filter过滤出偶数，返回新数组
const evens = numbers.filter(num => num % 2 === 0);
console.log('filter结果:', evens); // 输出: [2, 4]

// 使用reduce计算所有元素的总和，初始值为0
const sum = numbers.reduce((accumulator, currentValue) => accumulator + currentValue, 0);
console.log('reduce结果:', sum); // 输出: 15

// 链式调用示例：先过滤出偶数，再平方，最后求和
const evenSquareSum = numbers
  .filter(num => num % 2 === 0) // 过滤偶数: [2, 4]
  .map(num => num * num)        // 平方: [4, 16]
  .reduce((acc, val) => acc + val, 0); // 求和: 20
console.log('链式调用结果:', evenSquareSum); // 输出: 20

